//! Simplified Chinese strings for slideshow and presenter controls.

pub(super) fn lookup(text: &str) -> Option<&'static str> {
    Some(match text {
        "End of slide show, click to exit." => "幻灯片放映结束，单击退出。",
        "Go to slide {slide}" => "跳转到第 {slide} 张幻灯片",
        "Click the slide to zoom in. Esc cancels." => "单击幻灯片以放大，按 Esc 取消。",
        "Slide {slide} of {total}" => "第 {slide} 张，共 {total} 张",
        "Close" => "关闭",
        "✏ on" => "✏ 已开启",
        "◉ on" => "◉ 已开启",
        "Black" => "黑屏",
        "White" => "白屏",
        "All" => "全部",
        "End" => "结束",
        "Slide {slide}   Total {total}" => "本页 {slide}   总计 {total}",
        "Slide timings recorded." => "已记录幻灯片放映计时。",
        "Zoom on" => "已放大",
        "Zoom…" => "放大…",
        "Zoom" => "缩放",
        "All slides" => "所有幻灯片",
        "First {count} slides" => "前 {count} 张幻灯片",
        "{slide}  Hidden" => "{slide}  已隐藏",
        "Presenter View" => "演讲者视图",
        "End Show" => "结束放映",
        "Next ▶" => "下一张 ▶",
        "◀ Previous" => "◀ 上一张",
        "Resume" => "继续",
        "Pause" => "暂停",
        "Reset" => "重置",
        "Black on" => "黑屏已开启",
        "White on" => "白屏已开启",
        "All slides on" => "已显示所有幻灯片",
        "Next" => "下一张",
        "End of slide show" => "幻灯片放映结束",
        "Notes" => "备注",
        "No notes." => "暂无备注。",
        _ => return None,
    })
}
